parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "categoria": {
      "type": "string",
      "enum": ["Ventas", "Soporte", "Facturacion", "RRHH"]
    },
    "tiene_adjunto": {
      "type": "boolean",
      "description": "Indica si el correo incluye un archivo adjunto procesado."
    },
    "tipo_adjunto": {
      "type": "string",
      "description": "Tipo o clasificación del archivo adjunto (ej: HOJA_DE_VIDA, FACTURA, DOCUMENTO_FISCAL, REPORTE_ERROR, NINGUNO)."
    },
    "detalle_adjunto": {
      "type": "string",
      "description": "Breve descripción o resumen de lo que contiene el archivo adjunto. Indicar 'Ninguno' si no hay adjunto."
    },
    "resumen": {
      "type": "string"
    },
    "obligatorios_completos": {
      "type": "boolean"
    },
    "obligatorios_obtenidos": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "campo": { "type": "string" },
          "valor": { "type": "string" }
        },
        "required": ["campo", "valor"]
      }
    },
    "obligatorios_faltantes": {
      "type": "array",
      "items": { "type": "string" }
    },
    "opcionales_obtenidos": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "campo": { "type": "string" },
          "valor": { "type": "string" }
        },
        "required": ["campo", "valor"]
      }
    },
    "opcionales_faltantes": {
      "type": "array",
      "items": { "type": "string" }
    },
    "accion_recomendada": {
      "type": "string"
    }
  },
  "required": [
    "categoria",
    "tiene_adjunto",
    "tipo_adjunto",
    "detalle_adjunto",
    "resumen",
    "obligatorios_completos",
    "obligatorios_obtenidos",
    "obligatorios_faltantes",
    "opcionales_obtenidos",
    "opcionales_faltantes",
    "accion_recomendada"
  ]
}
